/**
 * Hosted dashboard deep-link for a serve session.
 *
 * Prefers the playground URL operators already use:
 * `https://cursor.com/dashboard/deployed-agents/<slug>/playground?sessionId=`
 * Falls back to `https://cursor.com/agents/<publicId>/<sessionId>` when the
 * slug is unknown. Returns undefined without a hosted public id so local
 * serve never emits a broken link.
 */
const PUBLIC_ID = /^asd_[0-9a-f]{32}$/;
const SLUG = /^[a-z0-9][a-z0-9_-]{0,63}$/;
export const AGENT_SERVE_PUBLIC_ID_ENV = "AGENT_SERVE_PUBLIC_ID";
export function dashboardSessionUrl(sessionId, opts) {
    const publicId = opts?.publicId ?? process.env[AGENT_SERVE_PUBLIC_ID_ENV];
    if (publicId === undefined || !PUBLIC_ID.test(publicId)) {
        return undefined;
    }
    const origin = (process.env.CURSOR_WEBSITE_URL ?? "https://cursor.com").replace(/\/$/, "");
    const slug = opts?.slug;
    if (slug !== undefined && SLUG.test(slug)) {
        return `${origin}/dashboard/deployed-agents/${slug}/playground?sessionId=${encodeURIComponent(sessionId)}`;
    }
    return `${origin}/agents/${publicId}/${encodeURIComponent(sessionId)}`;
}
